function counts(lv){let c={EASY:0,FAILED:0,HARD:0,UNKNOWN:0,CLEAR:0,EXHARD:0,FC:0}, lamps=bestLamps(),total=0;for(const [k,x]of catalog){if(x.level!==+lv)continue;let l=lamps.get(k);if(l==='NO_RECORD'||l==='NOPLAY')continue;total++;c[normalizeLamp(l)] = (c[normalizeLamp(l)]||0)+1;}return {c,total};}
