function bounds(date,mode){let d=parseDay(date),from,to;if(mode==='day'){from=to=date;}else if(mode==='week'){from=shift(date,-((d.getUTCDay()+6)%7));to=shift(from,6);}else{from=date.slice(0,7)+'-01';to=dayISO(new Date(Date.UTC(d.getUTCFullYear(),d.getUTCMonth()+1,0)));}return {from,to};}
