function periodStats(date,mode){let {from,to}=bounds(date,mode),rows=allResults().filter(e=>e.date&&e.date>=from&&e.date<=to),events=newLampEvents().filter(e=>e.date>=from&&e.date<=to),known=rows.filter(e=>e.notes!==null&&e.notes!==undefined),plays=rows.reduce((n,e)=>n+(e.plays||1),0),knownPlays=known.reduce((n,e)=>n+(e.plays||1),0),total=known.reduce((n,e)=>n+e.notes*(e.plays||1),0),denom=daysBetween(from,to)+1;return {from,to,rows,plays,knownPlays,notes:known.length?total:null,clears:events.filter(e=>e.kind==='upgrade').length,first:events.filter(e=>e.kind==='firstObserved').length,average:known.length?total/denom:null,activeAverage:known.length?total/new Set(rows.map(e=>e.date)).size:null};}
function deltaText(now,prev,unit=''){if(now===null||prev===null)return '比較できる記録が不足';if(prev===0)return now===0?'前期間と同じ':'前期間0 → '+fmt(now)+unit;let diff=(now-prev)/prev*100;return `${diff>=0?'+':''}${diff.toFixed(1)}% · 前期間比`;} 
function activityView(){let cur=periodStats(focusDate,period),prev=periodStats(previousDate(focusDate,period),period),week=periodStats(focusDate,'week'),has=cur.rows.length>0,label=period==='day'?'日':period==='week'?'週':'月',series=[];for(let i=-7;i<=0;i++){let d=previousDate(focusDate,period,i),s=periodStats(d,period),v=metric==='notes'?s.notes:metric==='plays'?(s.rows.length?s.plays:null):(s.rows.length||s.clears?s.clears:null);series.push({label:s.from.slice(5).replace('-','/'),v});}let chartPoints=series.filter(x=>x.v!==null);return `<div class="eyebrow">YOUR RHYTHM, YOUR PROGRESS</div><h1>アクティビティ</h1><p class="lead">積んだ練習を、見えるエネルギーに。</p><div class="tabs">${[['day','日'],['week','週'],['month','月']].map(([k,v])=>`<button class="${period===k?'active':''}" data-period="${k}">${v}</button>`).join('')}</div><div class="row between gap"><button class="btn small quiet" data-action="prev-period" aria-label="前の期間">←</button><div class="period-label">${cur.from.replaceAll('-','/')} ${cur.from===cur.to?'':'— '+cur.to.slice(5).replace('-','/')} <span class="muted">JST</span></div><button class="btn small quiet" data-action="next-period" aria-label="次の期間">→</button><button class="linkbtn" data-action="current-period">今${label}</button></div>
<section class="card"><div class="row between"><h2>この週のゴール</h2><span class="tag">月曜始まり</span></div><div class="meta">${week.from.slice(5).replace('-','/')} — ${week.to.slice(5).replace('-','/')} · ${focusDate>dateToday()?'選択期間':'記録済み分'}</div><div class="rings">${ring('打鍵数（推計）',week.notes,store.goals.notes,'#51e5d4')}${ring('プレー',week.rows.length?week.plays:null,store.goals.plays,'#83a8ff')}${ring('新規ランプ',week.rows.length?week.clears:null,store.goals.newLamps,'#ed83b5')}</div><details><summary>週目標を設定</summary><form id="goal-form"><div class="fields"><label class="field"><span>打鍵数 / 週</span><input name="notes" type="number" min="1" step="1" value="${store.goals.notes||''}" placeholder="例：30000"></label><label class="field"><span>プレー回数 / 週</span><input name="plays" type="number" min="1" step="1" value="${store.goals.plays||''}" placeholder="例：20"></label><label class="field"><span>新規ランプ / 週</span><input name="newLamps" type="number" min="1" step="1" value="${store.goals.newLamps||''}" placeholder="例：3"></label></div><button class="btn small primary spaced" type="submit">目標を保存</button></form></details></section>
${!has?`<section class="card">${empty('ここから、活動を積み重ねよう','この期間に日付つきのログはありません。日付の分からない過去リザルトは集計しません。',`<button class="btn primary" data-nav="input">最初のリザルトを記録</button>`)}</section>`:`<section class="card"><div class="eyebrow">${label}の記録</div><div class="stats"><div class="stat"><div class="stat-label">プレー</div><div class="big" data-test="activity-plays">${fmt(cur.plays)}<small> 回</small></div><div class="delta">${deltaText(cur.plays,prev.rows.length?prev.plays:null,'回')}</div></div><div class="stat"><div class="stat-label">新規ランプ</div><div class="big" data-test="activity-clears">${cur.clears}<small> 件</small></div><div class="delta">${deltaText(cur.clears,prev.rows.length?prev.clears:null,'件')}</div></div><div class="stat"><div class="stat-label">1日平均 打鍵</div><div class="big">${cur.average===null?'—':fmt(Math.round(cur.average))}</div><div class="meta">${period==='week'?'7日':period==='day'?'1日':daysBetween(cur.from,cur.to)+1+'日'}で割った値</div></div></div><div class="divider"></div><div class="row between"><div><div class="stat-label">総打鍵数 · 譜面ノーツ × プレー数</div><div class="big" data-test="activity-notes">${cur.notes===null?'—':fmt(cur.notes)}<small> notes</small></div></div><span class="delta">${deltaText(cur.notes,prev.notes)}</span></div><div class="help">ノーツ既知 ${cur.knownPlays}/${cur.plays}プレー ${cur.knownPlays<cur.plays?'· 不明分は含みません':''}。${cur.activeAverage!==null?'プレー日平均 '+fmt(Math.round(cur.activeAverage))+' notes。':''}フル譜面換算の推計で、途中FAILEDやCN/HCNの物理打鍵数とは異なります。</div><div class="help">この期間の上位更新：${['EASY','CLEAR','HARD','EXHARD','FC'].map(l=>l+' ＋'+newLampEvents().filter(e=>e.date>=cur.from&&e.date<=cur.to&&e.kind==='upgrade'&&e.lamp===l).length).join(' / ')}</div>${cur.first?`<div class="help">初観測のクリア ${cur.first}件は、以前のランプ不明のため新規ランプ数から除外。</div>`:''}</section>`}
<section class="card"><h2>積み重ねの推移</h2><div class="tabs">${[['notes','打鍵数'],['plays','プレー'],['clears','新規ランプ']].map(([k,v])=>`<button data-metric="${k}" class="${metric===k?'active':''}">${v}</button>`).join('')}</div>${chartPoints.length?svgActivity(series):empty('推移は記録してから','ノーツ数やプレー日が分かるログが増えると、日・週・月の変化を表示します。')}<div class="help">直近8期間。空白は未記録（0回とは断定しません）。線は記録のある連続期間だけを結びます。</div></section>
<section class="card"><h2>${focusDate.slice(0,7).replace('-','年')}月のプレー日</h2>${calendarHTML(focusDate.slice(0,7))}<div class="legend"><span><i class="dot" style="background:var(--cyan)"></i>記録あり</span><span>空白＝未記録 · JST</span></div></section>
<section class="card"><h2>e-amusement 累積記録</h2><p class="help">公式の総打鍵数・プレー回数を手動保存できます。譜面ログとは別系列で、二重加算しません。2つの観測間の差分だけを表示します。</p><form id="counter-form"><div class="fields spaced"><label class="field"><span>観測日（JST）</span><input type="date" name="date" value="${dateToday()}" max="${dateToday()}" required></label><label class="field"><span>集計系列 / バージョン</span><input name="series" value="IIDX34" maxlength="50" required></label><label class="field"><span>累積 総打鍵数</span><input type="number" name="notes" min="0" step="1" placeholder="任意"></label><label class="field"><span>累積 プレー回数</span><input type="number" name="plays" min="0" step="1" placeholder="任意"></label></div><button class="btn" type="submit">累積記録を保存</button></form>${counterHTML()}</section>`;}
function svgActivity(points){const w=540,h=170,l=38,r=20,t=20,b=30,known=points.filter(p=>p.v!==null),max=Math.max(...known.map(p=>p.v),1)*1.15,x=i=>l+i*(w-l-r)/7,y=v=>t+(max-v)/max*(h-t-b);let chunks=[],chunk=[];points.forEach((p,i)=>{if(p.v===null){if(chunk.length)chunks.push(chunk);chunk=[];}else chunk.push([x(i),y(p.v)]);});if(chunk.length)chunks.push(chunk);return `<svg class="chart" viewBox="0 0 ${w} ${h}" role="img" aria-label="${esc(points.map(p=>p.label+': '+(p.v??'未記録')).join('、'))}">${[0,max/2,max].map(v=>`<line class="gridline" x1="${l}" x2="${w-r}" y1="${y(v)}" y2="${y(v)}"/><text x="${l-6}" y="${y(v)+3}" text-anchor="end">${v>=1000?(v/1000).toFixed(0)+'k':Math.round(v)}</text>`).join('')}${chunks.map(c=>`<polyline points="${c.map(p=>p.join(',')).join(' ')}" fill="none" stroke="var(--cyan)" stroke-width="2.5"/>`).join('')}${points.map((p,i)=>`${p.v===null?'':`<circle cx="${x(i)}" cy="${y(p.v)}" r="4" fill="var(--cyan)"/>`}${i%2===0||i===7?`<text x="${x(i)}" y="${h-8}" text-anchor="middle">${p.label}</text>`:''}`).join('')}</svg>`;}
function counterHTML(){let rows=[...store.counters].sort((a,b)=>a.series.localeCompare(b.series)||a.date.localeCompare(b.date));if(!rows.length)return `<div class="help">まだ累積記録はありません。異なる週にまたがる差分は日別・週別へ推測配分しません。</div>`;return rows.map((c,i)=>{let prev=rows.slice(0,i).filter(x=>x.series===c.series).at(-1),dn=prev&&c.notes!==null&&prev.notes!==null?c.notes-prev.notes:null,dp=prev&&c.plays!==null&&prev.plays!==null?c.plays-prev.plays:null,reset=dn<0||dp<0;return `<div class="list-item"><div class="row between"><div><strong>${c.date} · ${esc(c.series)}</strong><div class="meta">総打鍵 ${c.notes===null?'—':fmt(c.notes)} / プレイ ${c.plays===null?'—':fmt(c.plays)}</div></div><button class="linkbtn" data-delete-counter="${esc(c.id)}" aria-label="累積記録を削除">削除</button></div><div class="help">${!prev?'最初の観測。差分は次の記録から。':reset?'累積値の減少を検知。リセット／訂正として差分は算出しません。':`${prev.date} → ${c.date} の差分：打鍵 ${dn===null?'—':'＋'+fmt(dn)} / プレー ${dp===null?'—':'＋'+fmt(dp)}（期間全体）`}</div></div>`;}).join('');}
function detailsView(){let chart=catalog.get(detailKey)||[...catalog.values()][0];detailKey=chart.key;let rows=allResults().filter(e=>chartKey(e.title,e.difficulty)===detailKey).sort((a,b)=>(a.date||a.knownAsOf).localeCompare(b.date||b.knownAsOf));let bp=rows.filter(e=>e.bp!==null),dated=bp.filter(e=>e.date),best=bestLamps().get(detailKey),first=dated[0],last=dated.at(-1),same=first&&last&&first.option===last.option,delta=dated.length>=2&&same?last.bp-first.bp:null;let timing=[...rows.filter(e=>e.fast!==null&&e.slow!==null),...DATA.timingObservations.filter(e=>chartKey(e.title,e.difficulty)===detailKey).map(e=>({...e,timingMetric:'GOOD',option:'不明',seed:true}))];return `<div class="eyebrow">CHART LAB</div><h1>成長の軌跡</h1><p class="lead">比べるのは、前の自分。</p><label class="field chart-select"><span>曲名で検索</span><input id="detail-search" type="search" placeholder="例：Line 4 Ruin" value="${esc(chartSearch)}"></label><label class="field chart-select"><span>譜面を選ぶ</span><select id="detail-chart">${chartOptions(detailKey,chartSearch)}</select></label><section class="card"><div class="row between"><span class="tag">☆${chart.level} ${chart.difficulty}</span>${lampTag(best)}</div><h2 style="margin-top:14px">${esc(chart.title)}</h2><p class="help">スナップショット EX SCORE ${esc(chart.ex_score??'—')} / DJ LEVEL ${esc(String(chart.dj_level||'—').replace('.gif',''))} · ${esc(DATA.snapshotAsOf)}</p><div class="stats"><div><div class="stat-label">最少BP（全記録）</div><div class="big" data-test="best-bp">${bp.length?Math.min(...bp.map(e=>e.bp),chart.bestMissCount??Infinity):'—'}</div></div><div><div class="stat-label">最新BP</div><div class="big">${bp.length?bp.at(-1).bp:'—'}</div></div><div><div class="stat-label">初回とのBP差</div><div class="big ${delta!==null&&delta<0?'ok':''}">${delta===null?'—':(delta>0?'+':'')+delta}</div></div></div>${dated.length?svgLine(dated.map(e=>({label:e.date.slice(5).replace('-','/'),v:e.bp})),'#83a8ff','BP'):empty('次の記録が、成長の起点','日付の分かるBPを記録すると、推移が表示されます。')}<div class="help">BPは低いほど良い。日付不明の結果は線にしません。${dated.length===1?'現在は1点だけ。次回から改善幅が見えます。':''}${dated.length>=2&&!same?'オプションが異なるため初回差は表示しません。':''} グラフは全オプションを表示し、一覧で配置を確認できます。</div></section>
<section class="card"><h2>FAST / SLOW</h2>${timing.length?timing.map(e=>{let total=e.fast+e.slow,pct=total?e.fast/total*100:null;return `<div class="list-item"><div class="row between"><strong>${e.date||'日付不明'}</strong><span class="tag">${e.timingMetric==='GOOD'?'GOOD内訳':e.timingMetric==='UNKNOWN'?'種別不明':'全FAST/SLOW'} · ${esc(e.option||'不明')}</span></div><div class="stack"><span style="width:${pct??50}%;background:var(--pink)"></span><span style="width:${pct===null?50:100-pct}%;background:var(--blue)"></span></div><div class="row between"><span>FAST <strong>${e.fast}</strong></span><span>SLOW <strong>${e.slow}</strong></span><span class="muted">${pct===null?'判定数0':pct.toFixed(1)+'% FAST'}</span></div></div>`;}).join(''):empty('タイミングも記録しよう','FAST・SLOWの両方を入力すると、偏りの変化を比較できます。')}<div class="help">GOOD内訳と全FAST/SLOWは混ぜて比較しません。判定数0の比率は算出しません。</div></section>
<section class="card"><div class="row between"><h2>この譜面のログ</h2><button class="btn primary small" data-input-chart="${esc(detailKey)}">＋ 記録</button></div>${rows.length?rows.slice().reverse().map(logItem).join(''):empty('まだログがありません','初めてのBPを残して、ここを成長の記録に。')}</section>`;}
function logItem(e){return `<div class="list-item"><div class="row between"><div><div class="songtitle">${esc(e.title)} (${e.difficulty})</div><div class="meta">${e.date||('プレー日不明 · '+e.knownAsOf+'までに確認')} · ${esc(e.option||'不明')}${e.plays>1?' · '+e.plays+'プレー':''}</div></div><strong class="count">BP ${e.bp===null?'—':e.bp}</strong></div><div class="row between" style="margin-top:8px">${e.lamp?lampTag(e.lamp):'<span class="tag">当時ランプ不明</span>'}${!e.seed?`<span><button class="linkbtn" data-edit="${esc(e.id)}">編集</button><button class="linkbtn" data-delete="${esc(e.id)}">削除</button></span>`:'<span class="meta">引き継ぎ記録</span>'}</div>${e.memo?`<div class="help">${esc(e.memo)}</div>`:''}${e.photoName||e.exScore!==null&&e.exScore!==undefined?`<details><summary>記録の判定内訳</summary><div class="help">${esc(e.photoName)}<br>${esc(e.playedAt||e.date)} (JST)<br>${esc(e.photoDateSource||e.dateSource)}<br>DJ LEVEL ${esc(e.djLevel||'—')} / EX SCORE ${e.exScore??'—'}<br>PGREAT ${e.pgreat??'—'} / GREAT ${e.great??'—'} / GOOD ${e.good??'—'}<br>BAD ${e.bad??'—'} / POOR ${e.poor??'—'} / CB ${e.comboBreak??'—'}</div></details>`:''}</div>`;}
function curriculumView(){let rows=DATA.curriculum.filter(s=>s.p===phase&&(slot==='all'||s.s===+slot)),best=bestLamps(),done=DATA.curriculum.filter(s=>s.p===phase&&(ORDER[normalizeLamp(best.get(chartKey(s.t,s.d)))]??-1)>=1).length,total=DATA.curriculum.filter(s=>s.p===phase).length;const names=['','八段取得','☆11地力＋九段対策','九段特攻'];return `<div class="eyebrow">YOUR TRAINING PLAN</div><h1>九段カリキュラム</h1><p class="lead">ルーティンはそのまま。選曲を、一歩先へ。</p><div class="tabs">${[1,2,3].map(p=>`<button data-phase="${p}" class="${phase===p?'active':''}">Phase ${p}</button>`).join('')}</div><section class="card"><div class="eyebrow">PHASE 0${phase}</div><h2>${names[phase]}</h2>${progress('候補譜面のEASY以上',done,total+'曲',done/total*100)}<div class="help">${phase===1?'八段合格・☆11 EASY以上60曲・☆10 FAILED55曲以下を目指す。':phase===2?'乱打・皿複合・縦連・CNを広く伸ばす。☆11 EASY80曲を目安に。':'九段曲を単曲で予習。旅人リランは粘着しすぎず、サンパラの中速乱打を鍛える。'}</div></section><div class="fields gap"><label class="field"><span>ルーティン枠</span><select id="slot-filter">${[['all','全枠'],['1','1 指ならし'],['2','2 弱めの特攻'],['3','3 高クリア率'],['4','4 高難度／☆11']].map(([v,t])=>`<option value="${v}" ${slot===v?'selected':''}>${t}</option>`).join('')}</select></label><label class="field"><span>状態</span><select id="status-filter"><option value="all">すべて</option>${[['uncleared','未クリア'],['cleared','EASY以上']].map(([v,t])=>`<option value="${v}" ${statusFilter===v?'selected':''}>${t}</option>`).join('')}</select></label></div><section class="card">${rows.filter(s=>{let cleared=(ORDER[normalizeLamp(best.get(chartKey(s.t,s.d)))]??-1)>=1;return statusFilter==='all'||statusFilter==='cleared'&&cleared||statusFilter==='uncleared'&&!cleared;}).map(s=>{let k=chartKey(s.t,s.d),l=best.get(k);return `<div class="list-item"><div class="row between"><span class="tag">枠 ${s.s} · ☆${s.lv} ${s.d}</span>${lampTag(l||'NO_RECORD')}</div><div class="songtitle" style="margin-top:9px">${esc(s.t)}</div><div class="meta">通常 ${s.c}% / EASY ${s.e}% · ${esc(s.tier)}</div><p class="help">${esc(s.aim)}${s.tag?' · '+esc(s.tag):''}</p><div class="row" style="margin-top:10px"><button class="btn small" data-show-chart="${esc(k)}">成長を見る</button><button class="btn small primary" data-input-chart="${esc(k)}">記録する</button></div></div>`;}).join('')||empty('条件に合う譜面がありません','枠や状態のフィルターを変えてみてください。')}</section><p class="help">クリア率はclearlamp登録者全体の累積値で、あなた個人の成功確率ではありません。未記録は一覧にない譜面であり、NO PLAYとは断定しません。</p>`;}
function inputView(){let e=editingId?store.entries.find(e=>e.id===editingId):null,key=e?chartKey(e.title,e.difficulty):coachSelection||detailKey,c=catalog.get(key)||[...catalog.values()][0],notes=e?.notes??c.notes??'';return `<div class="eyebrow">SAVE YOUR NEXT STEP</div><h1>${e?'リザルトを編集':'今日のリザルト'}</h1><p class="lead">1曲の挑戦も、立派な積み重ね。</p><div class="row gap"><button class="btn primary" data-nav="photos">▧ 写真をまとめて取り込む</button></div><section class="card"><form id="result-form"><div class="fields"><label class="field full"><span>曲名で検索</span><input id="input-search" type="search" placeholder="曲名の一部を入力"></label><label class="field full"><span>譜面 *</span><select id="result-chart" name="chart" required>${chartOptions(c.key)}</select></label><label class="field"><span>プレー日（JST）*</span><input name="date" type="date" value="${e?.date||dateToday()}" max="${dateToday()}" required></label><label class="field"><span>ランプ *</span><select name="lamp">${LAMPS.map(l=>`<option ${e?.lamp===l||(!e&&l==='FAILED')?'selected':''}>${l}</option>`).join('')}</select></label><label class="field"><span>BP / MISS COUNT</span><input name="bp" type="number" min="0" max="99999" step="1" value="${e?.bp??''}" placeholder="不明なら空欄"></label><label class="field"><span>オプション</span><select name="option">${['正規','MIRROR','RANDOM','S-RANDOM','R-RANDOM','不明'].map(o=>`<option ${(e?.option||'正規')===o?'selected':''}>${o}</option>`).join('')}</select></label><label class="field"><span>FAST</span><input name="fast" type="number" min="0" max="99999" step="1" value="${e?.fast??''}" placeholder="任意"></label><label class="field"><span>SLOW</span><input name="slow" type="number" min="0" max="99999" step="1" value="${e?.slow??''}" placeholder="任意"></label><label class="field"><span>判定の種別</span><select name="timingMetric"><option value="ALL">全FAST / SLOW</option><option value="GOOD" ${e?.timingMetric==='GOOD'?'selected':''}>GOODの内訳</option><option value="UNKNOWN" ${e?.timingMetric==='UNKNOWN'?'selected':''}>種別不明</option></select></label><label class="field"><span>プレー回数 *</span><input name="plays" type="number" min="1" max="999" step="1" value="${e?.plays||1}" required></label></div><p class="help">通常は1プレー。複数回をまとめる場合、BP・判定は最後の1回の値として保存します。実際に遊んだ日で記録してください。</p><details ${notes!==''?'open':''}><summary>活動量用ノーツ数 / メモ</summary><div class="fields"><label class="field"><span>譜面の総ノーツ数</span><input id="result-notes" name="notes" type="number" min="0" max="99999" step="1" value="${notes}" placeholder="不明は空欄"></label><label class="field"><span>ノーツ数の出典</span><input id="result-notes-source" name="notesSource" maxlength="500" value="${esc(e?.notesSource||c.notesSource||'')}" placeholder="textage URL / 手入力"></label><label class="field full"><span>メモ</span><textarea name="memo" maxlength="1000" placeholder="皿が取れた、終盤HCNを離した、など">${esc(e?.memo||'')}</textarea></label></div><p class="help">打鍵数は総ノーツ×回数の推計。ノーツ不明は未集計にします。出典は確認済みの譜面ページか「手入力」を指定。既知データは自動で補完します。</p></details><div class="form-actions"><button class="btn primary" type="submit" id="save-result">${e?'変更を保存':'リザルトを保存'}</button>${e?'<button class="btn quiet" type="button" data-action="cancel-edit">キャンセル</button>':''}</div><div class="help">端末内だけに保存します。ときどきJSONでバックアップを。</div></form></section><section class="card"><div class="row between"><h2>最近の記録</h2><span class="tag">${allResults().length}件の記録</span></div>${allResults().length?[...allResults()].sort((a,b)=>(b.date||b.knownAsOf||'').localeCompare(a.date||a.knownAsOf||'')||(b.playedAt||b.createdAt||'').localeCompare(a.playedAt||a.createdAt||'')).slice(0,50).map(logItem).join(''):empty('次の1曲から、はじめよう','過去9件は「成長」から確認できます。実際のプレー結果を入力してください。')}</section>`;}
function backupObject(){return {appId:'iidx-coach',schemaVersion:1,exportedAt:new Date().toISOString(),timezone:'Asia/Tokyo',entries:store.entries,counters:store.counters,goals:store.goals,dan:store.dan,seed:DATA};}
function dataView(){return `<div class="eyebrow">YOUR DATA, YOUR CONTROL</div><h1>データと設定</h1><p class="lead">コーチへの共有も、機種変更も、JSONで。</p>${storageError?`<div class="warning">${esc(storageError)}</div>`:''}<section class="card"><h2>バックアップ / 取り込み</h2><p class="help">追加ログ・累積記録・目標・初期データをJSONに保存。取り込みはIDで重複を除き、既存ログを消さずに追加します。同じIDで内容が違う記録は既存を維持します。</p><div class="row spaced"><button id="export-json" class="btn primary" data-action="export">JSONを書き出す</button><button class="btn" data-action="copy-json">JSONを表示</button></div><label class="field"><span>バックアップJSONを選ぶ（最大20MB）</span><input id="import-file" type="file" accept=".json,application/json"></label><details><summary>JSONを貼り付けて取り込む</summary><label class="field"><span>JSON本文</span><textarea id="import-text" placeholder="バックアップのJSONを貼り付け"></textarea></label><button class="btn small spaced" data-action="preview-text">内容を確認</button></details><div id="import-preview">${importPreviewHTML()}</div><textarea id="export-text" aria-label="書き出しJSON" hidden readonly></textarea><p class="help">初期seedは参照用。取り込み時に初期ランプを上書きせず、entriesだけを安全に統合します。コーチの更新も同じ形式で追加できます。</p></section>
<section class="card"><h2>この端末の表示名</h2><label class="field"><span>表示名（30文字まで・端末内のみ）</span><input id="display-name" type="text" maxlength="30" value="${esc(store.displayName||'PLAYER')}"></label><div class="help">表示名はlocalStorageだけに保存し、公開データやバックアップへ含めません。</div></section><section class="card"><h2>共有スナップショット</h2><div class="help" id="remote-status">${esc(window.IIDXSnapshot?.status||'最新データを確認中')} · ${esc(DATA.snapshotAsOf)} (JST)</div><p class="help">ランプ・スコアは公開の最新データを読み込みます。手入力・写真の結果は端末に残し、送信・上書きしません。</p></section><section class="card"><h2>段位の到達</h2><label class="field"><span>実際に合格した段位</span><select id="dan-select">${['七段','八段','九段'].map(v=>`<option ${store.dan===v?'selected':''}>${v}</option>`).join('')}</select></label><div class="help">合格したときだけ変更してください。Phase 1の目標と八段バッジに反映します。</div></section>
<section class="card"><h2>保存について</h2><p class="help">データはこのブラウザー・このURLのlocalStorage内です。他端末やPageには自動同期しません。サイトデータ削除・プライベートブラウズ終了で消える場合があります。file://版とHTTPS版も保存先が異なるため、JSONで移してください。</p><div class="divider"></div><div class="row between"><span class="muted">引き継ぎ記録</span><strong>${DATA.charts.length}譜面 / BP ${DATA.results.length}件</strong></div><div class="row between"><span class="muted">端末で追加</span><strong>${store.entries.length}件 / 累積 ${store.counters.length}件</strong></div><p class="help">各譜面の初期BPは1点だけ。11/4は7件の確認日でプレー日ではありません。clflg0はランプ不明。clflg5の4曲はHARD相当・未検証。</p></section><section class="card"><h2>アプリを使いやすく</h2><p class="help">HTTPSのPWA版はブラウザーのメニューからホーム画面に追加できます。file://版はインストール・Service Workerなしで使える単体版です。初回のHTTPS読み込み後はオフライン対応。公式API・アカウント連携はありません。リザルト写真は端末内OCRで取り込めます。</p><p class="help">非公式の個人向けコーチングツール。beatmania IIDXの公式サービスではありません。</p></section>`;}
function importPreviewHTML(){if(!pendingImport)return '';let old=new Set(store.entries.map(e=>e.id)),added=pendingImport.entries.filter(e=>!old.has(e.id)).length,conflicts=pendingImport.entries.filter(e=>old.has(e.id)&&JSON.stringify(store.entries.find(x=>x.id===e.id))!==JSON.stringify(e)).length;return `<div class="warning"><strong>取り込み前の確認</strong><br>リザルト ${pendingImport.entries.length}件（追加 ${added} / 重複 ${pendingImport.entries.length-added}）<br>累積 ${pendingImport.counters.length}件。競合 ${conflicts}件は既存データを維持します。</div><label class="check"><input id="import-settings" type="checkbox"><span>目標と段位も取り込む（既存の設定を上書き）</span></label><div class="row spaced"><button id="confirm-import" class="btn primary" data-action="confirm-import">確認して取り込む</button><button class="btn" data-action="cancel-import">キャンセル</button></div>`;}
function render(){catalog=buildCatalog();const header=document.querySelector('.profile b');if(header)header.textContent=store.displayName||'PLAYER';const views={home:homeView,activity:activityView,charts:detailsView,curriculum:curriculumView,input:inputView,data:dataView,photos:()=>window.IIDXPhotos?window.IIDXPhotos.render():'写真機能を読み込み中です'};$('#main').innerHTML=(storageError&&tab!=='data'?`<div class="warning">${esc(storageError)}</div>`:'')+views[tab]();document.querySelectorAll('.nav button').forEach(b=>{b.classList.toggle('active',b.dataset.nav===tab||(tab==='photos'&&b.dataset.nav==='input'));b.setAttribute('aria-current',b.dataset.nav===tab?'page':'false');});$('#footnote').textContent='PLAYER IIDX COACH · 非公式 / データは端末内 · JST';window.__iidx={store,counts,periodStats,newLampEvents,backupObject,buildCatalog,streaks,allResults};if(tab==='photos')window.IIDXPhotos?.afterRender();}
function navigate(t){tab=t;render();window.scrollTo({top:0,behavior:'instant'});}
function id(){return globalThis.crypto?.randomUUID?.()||'log-'+Date.now()+'-'+Math.random().toString(36).slice(2);}
function downloadJSON(){const blob=new Blob([JSON.stringify(backupObject(),null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='iidx-PLAYER-'+dateToday()+'.json';document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('JSONを書き出しました。安全な場所に保管してください。');}
function previewImport(text){if(text.length>20*1024*1024)throw Error('20MB以下のJSONを選んでください。');let obj=JSON.parse(text);if((obj.appId!=='iidx-coach'&&!/^[a-z0-9-]+-iidx-coach$/.test(obj.appId||''))||obj.schemaVersion!==1)throw Error('対応するバックアップ（schemaVersion: 1）ではありません。');pendingImport=validateStore(obj);$('#import-preview').innerHTML=importPreviewHTML();toast('内容を確認してから取り込んでください。');}
document.addEventListener('click',e=>{let b=e.target.closest('button');if(!b)return;try{if(b.dataset.nav){if(b.dataset.nav==='input'){editingId=null;coachSelection=null;}navigate(b.dataset.nav);return;}if(b.dataset.level){level=+b.dataset.level;render();return;}if(b.dataset.phase){phase=+b.dataset.phase;render();return;}if(b.dataset.period){period=b.dataset.period;render();return;}if(b.dataset.metric){metric=b.dataset.metric;render();return;}if(b.dataset.showChart){detailKey=b.dataset.showChart;chartSearch='';navigate('charts');return;}if(b.dataset.inputChart){coachSelection=b.dataset.inputChart;editingId=null;navigate('input');return;}if(b.dataset.edit){editingId=b.dataset.edit;navigate('input');return;}if(b.dataset.delete){const result=store.entries.find(x=>x.id===b.dataset.delete);if(!confirm('このリザルトを削除しますか？ JSONバックアップがあれば復元できます。'))return;store.entries=store.entries.filter(x=>x.id!==b.dataset.delete);save();render();toast('削除しました。ランプと活動量を再計算しました。');return;}if(b.dataset.deleteCounter){if(!confirm('この累積記録を削除しますか？'))return;store.counters=store.counters.filter(x=>x.id!==b.dataset.deleteCounter);save();render();return;}
switch(b.dataset.action){case 'prev-period':focusDate=previousDate(focusDate,period);render();break;case 'next-period':focusDate=previousDate(focusDate,period,1);render();break;case 'current-period':focusDate=dateToday();render();break;case 'cancel-edit':editingId=null;render();break;case 'export':downloadJSON();break;case 'copy-json':{let el=$('#export-text');el.hidden=false;el.value=JSON.stringify(backupObject(),null,2);el.style.minHeight='180px';el.focus();el.select();toast('JSONを表示しました。選択してコピーできます。');break;}case 'preview-text':previewImport($('#import-text').value);break;case 'cancel-import':pendingImport=null;$('#import-preview').innerHTML='';break;case 'confirm-import':{if(!pendingImport)return;let ids=new Set(store.entries.map(x=>x.id)),cs=new Set(store.counters.map(x=>x.id));let added=pendingImport.entries.filter(x=>!ids.has(x.id));store.entries.push(...added);store.counters.push(...pendingImport.counters.filter(x=>!cs.has(x.id)));if($('#import-settings')?.checked){store.goals=pendingImport.goals;store.dan=pendingImport.dan;}pendingImport=null;save();render();toast(`${added.length}件のリザルトを追加しました。重複は追加していません。`);break;}}}catch(err){toast(err.message||String(err));}});
document.addEventListener('change',async e=>{const el=e.target;try{if(el.id==='display-name'){store.displayName=el.value.trim().slice(0,30)||'PLAYER';save();const header=document.querySelector('.profile b');if(header)header.textContent=store.displayName;toast('表示名をこの端末だけに保存しました。');}if(el.id==='detail-chart'){detailKey=el.value;render();}if(el.id==='slot-filter'){slot=el.value;render();}if(el.id==='status-filter'){statusFilter=el.value;render();}if(el.id==='dan-select'){store.dan=el.value;save();toast('段位を更新しました。');}if(el.id==='result-chart'){let c=catalog.get(el.value);$('#result-notes').value=c?.notes??'';$('#result-notes-source').value=c?.notesSource||'';}if(el.id==='import-file'&&el.files[0]){if(el.files[0].size>20*1024*1024)throw Error('20MB以下のファイルを選んでください。');previewImport(await el.files[0].text());}}catch(err){pendingImport=null;toast(err.message||'取り込みに失敗しました。');}});
document.addEventListener('input',e=>{let el=e.target;if(el.id==='detail-search'){chartSearch=el.value;let target=$('#detail-chart');target.innerHTML=chartOptions(detailKey,el.value);if(!target.options.length)target.innerHTML='<option value="">該当なし</option>';}if(el.id==='input-search'){let target=$('#result-chart'),old=target.value;target.innerHTML=chartOptions(old,el.value);if(!target.options.length)target.innerHTML='<option value="">該当なし</option>';let c=catalog.get(target.value);$('#result-notes').value=c?.notes??'';$('#result-notes-source').value=c?.notesSource||'';}});
document.addEventListener('submit',e=>{e.preventDefault();const form=e.target,f=new FormData(form);try{if(form.id==='result-form'){let c=catalog.get(f.get('chart'));if(!c)throw Error('譜面を選択してください。');const old=store.entries.find(x=>x.id===editingId);let entry=validateEntry({...old,playedAt:old?.playedAt?String(f.get('date'))+old.playedAt.slice(10):null,id:editingId||id(),title:c.title,difficulty:c.difficulty,level:c.level,date:f.get('date'),lamp:f.get('lamp'),bp:f.get('bp'),fast:f.get('fast'),slow:f.get('slow'),option:f.get('option'),plays:f.get('plays'),notes:f.get('notes'),notesSource:f.get('notesSource'),timingMetric:f.get('timingMetric'),memo:f.get('memo'),createdAt:old?.createdAt||new Date().toISOString()});if(editingId){store.entries=store.entries.map(x=>x.id===editingId?entry:x);}else store.entries.push(entry);detailKey=c.key;editingId=null;coachSelection=c.key;save();render();toast('リザルトを保存しました。おつかれさま！');}if(form.id==='goal-form'){store.goals={notes:integerOrNull(f.get('notes')),plays:integerOrNull(f.get('plays')),newLamps:integerOrNull(f.get('newLamps'))};save();render();toast('週目標を保存しました。');}if(form.id==='counter-form'){let c=validateCounter({id:id(),date:f.get('date'),series:f.get('series'),notes:f.get('notes'),plays:f.get('plays')});if(store.counters.some(x=>x.date===c.date&&x.series===c.series))throw Error('同じ日・系列の観測があります。削除してから修正してください。');store.counters.push(c);save();render();toast('累積値を保存しました。');}}catch(err){toast(err.message||String(err));}});
window.IIDXApp={getCatalog:()=>catalog,getEntries:()=>store.entries,chartKey,validateEntry,toast,navigate,addPhotoResults(entries){const checked=entries.map(validateEntry),ids=new Set(store.entries.map(e=>e.id));if(checked.some(e=>ids.has(e.id)))throw Error('同じ写真の記録IDが保存済みです。');const previous=store.entries;store.entries=[...previous,...checked];if(!save()){store.entries=previous;throw Error('端末保存ができません。保存領域・ブラウザー設定を確認し、手動JSONでバックアップしてください。');}render();return checked.length;}};
render();
if('serviceWorker'in navigator&&location.protocol!=='file:'){window.addEventListener('load',()=>navigator.serviceWorker.register('./sw.js').catch(()=>{}));}
/* Shared records are additive; local user records are never overwritten. */
const sharedResultIDs=new Set(DATA.results.filter(e=>e.source==='verified-photo-transcription').map(e=>e.id));
function snapshotForCache(){return {schemaVersion:1,snapshotAsOf:DATA.snapshotAsOf,baselineAsOf:DATA.baselineAsOf,charts:DATA.charts,results:DATA.results.filter(e=>sharedResultIDs.has(e.id))};}
function applyPublicSnapshot(snapshot){
 if(!snapshot||snapshot.schemaVersion!==1||!validDate(snapshot.snapshotAsOf)||snapshot.snapshotAsOf>dateToday()||!Array.isArray(snapshot.charts)||!snapshot.charts.length||snapshot.charts.length>10000)throw Error('最新データの形式が正しくありません。');
 if(snapshot.snapshotAsOf<DATA.snapshotAsOf)return false;
 const rows=snapshot.charts.map(x=>{if(!x||typeof x.title!=='string'||!x.title.trim()||x.title.length>250||!['N','H','A','L'].includes(x.difficulty)||!Number.isInteger(+x.level)||+x.level<1||+x.level>12||!['UNKNOWN','FAILED','ASSIST','EASY','CLEAR','HARD','HARD_UNVERIFIED','EXHARD','FC'].includes(x.lamp))throw Error('最新データの譜面が不正です。');let out={title:x.title.trim(),difficulty:x.difficulty,level:+x.level,lamp:x.lamp};for(const k of ['ex_score','pgreat','great'])if(x[k]!==undefined){let n=integerOrNull(x[k],99999);if(n!==null)out[k]=String(n);}for(const k of ['bestExScore','bestMissCount','lastExScore','lastMissCount','notes'])if(x[k]!==undefined){let n=integerOrNull(x[k],99999);if(n!==null)out[k]=n;}if(x.notesSource!==undefined)out.notesSource=String(x.notesSource).slice(0,500);if(x.baselineLamp&&Object.hasOwn(ORDER,x.baselineLamp))out.baselineLamp=x.baselineLamp;if(x.dj_level!==undefined)out.dj_level=String(x.dj_level).replace('.gif','').slice(0,10);if(typeof x.lastPlayedAt==='string')out.lastPlayedAt=x.lastPlayedAt.slice(0,40);return out;});
 const seen=new Set();for(const x of rows){const key=chartKey(x.title,x.difficulty);if(seen.has(key))throw Error('最新データに譜面の重複があります。');seen.add(key);}
 if(snapshot.results!==undefined&&(!Array.isArray(snapshot.results)||snapshot.results.length>50000))throw Error('共有リザルトの形式が不正です。');
 const records=(snapshot.results||[]).map(e=>{const out=validateEntry(e);if(out.date>snapshot.snapshotAsOf)throw Error('共有リザルトの日付が不正です。');return out;});
 const combined=new Map(DATA.charts.map(x=>[chartKey(x.title,x.difficulty),x]));for(const x of rows){const key=chartKey(x.title,x.difficulty),old=combined.get(key)||{notes:null,notesSource:null};const merged={...old,...x};merged.baselineLamp=old.baselineLamp||old.lamp||x.baselineLamp||'UNKNOWN';merged.bestExScore=Math.max(+old.bestExScore||+old.ex_score||0,+x.bestExScore||+x.ex_score||0);const misses=[old.bestMissCount,x.bestMissCount].filter(v=>v!==undefined&&v!==null);if(misses.length)merged.bestMissCount=Math.min(...misses);if(+old.ex_score>+x.ex_score)for(const k of ['ex_score','pgreat','great','dj_level'])if(old[k]!==undefined)merged[k]=old[k];combined.set(key,merged);}
 for(const e of records){const key=chartKey(e.title,e.difficulty);if(!combined.has(key))combined.set(key,{title:e.title,difficulty:e.difficulty,level:e.level,lamp:e.lamp,baselineLamp:e.previousLamp||'UNKNOWN',notes:e.notes,notesSource:e.notesSource});}
 const history=new Map(DATA.results.map(e=>[e.id,e]));for(const e of records){history.set(e.id,e);sharedResultIDs.add(e.id);}
 DATA.results=[...history.values()];DATA.charts=[...combined.values()];DATA.snapshotAsOf=snapshot.snapshotAsOf;catalog=buildCatalog();
 if(!['input','photos'].includes(tab)&&!document.querySelector('input:focus,textarea:focus,select:focus'))render();return true;
}
window.IIDXApp.applySnapshot=applyPublicSnapshot;
window.IIDXApp.snapshotForCache=snapshotForCache;
